 <?php $__env->startSection('title','Proses Order'); ?> <?php $__env->startSection('header','Proses Order'); ?> <?php $__env->startSection('content'); ?>
<div class="page-head"><div><h2><?php echo e($order->order_number); ?></h2><span class="badge badge-<?php echo e($order->status); ?>"><?php echo e($order->status_label); ?></span></div><a class="btn btn-secondary" href="<?php echo e(route('omd.orders.index')); ?>">Kembali</a></div>
<div class="grid2"><div><div class="card"><h3>Informasi Order</h3><div class="detail-grid"><div class="detail-item"><span>User</span><strong><?php echo e($order->user->name); ?></strong></div><div class="detail-item"><span>Area</span><strong><?php echo e($order->area->category); ?> - <?php echo e($order->area->name); ?></strong></div><div class="detail-item"><span>Produk</span><strong><?php echo e($order->product->name); ?></strong></div><div class="detail-item"><span>Model</span><strong><?php echo e($order->model ?: '-'); ?></strong></div><div class="detail-item"><span>Jenis NG</span><strong><?php echo e($order->ngType->code); ?> - <?php echo e($order->ngType->name); ?></strong></div><div class="detail-item"><span>Quantity</span><strong><?php echo e($order->quantity); ?></strong></div></div><p class="muted" style="margin-top:16px"><?php echo e($order->description ?: 'Tidak ada keterangan.'); ?></p></div>
